/*
 * Host-side known-answer tests for the kernel's crypto and
 * checksum code. Compiles the real kernel sources (no copies)
 * against vectors generated by independent implementations
 * (see gen_vectors.py) plus a few published vectors.
 */
#include <stdio.h>
#include <string.h>
#include <stdint.h>

#include "sha256.h"
#include "hmac_sha256.h"
#include "pbkdf2.h"
#include "aes256.h"
#include "checksum.h"
#include "net_byteorder.h"

#include "vectors.h"
#include "sbox_ref.h"

uint8_t aes256_sbox_for_test(uint8_t x);

static int passed = 0, failed = 0;

static void check(int ok, const char* name)
{
    if (ok) { passed++; printf("  PASS  %s\n", name); }
    else    { failed++; printf("  FAIL  %s\n", name); }
}

static int unhex(const char* hex, uint8_t* out, size_t n)
{
    for (size_t i = 0; i < n; i++)
    {
        unsigned v;
        if (sscanf(hex + 2 * i, "%2x", &v) != 1) return 0;
        out[i] = (uint8_t)v;
    }
    return 1;
}

static void test_sha256(void)
{
    printf("== SHA-256 ==\n");

    uint8_t d[32], e[32];

    sha256("abc", 3, d);
    unhex("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad", e, 32);
    check(memcmp(d, e, 32) == 0, "published vector: \"abc\"");

    int all = 1;
    for (int l = 0; l < 131; l++)
    {
        sha256(sha_input, (uint32_t)l, d);
        if (memcmp(d, sha_expect[l], 32) != 0) { all = 0; printf("    mismatch at length %d\n", l); }
    }
    check(all, "lengths 0..130 match reference (all padding boundaries)");

    /* Incremental update with awkward chunk sizes must equal one-shot. */
    sha256_ctx_t c;
    sha256_init(&c);
    uint32_t pos = 0, step = 1;
    while (pos < 131)
    {
        uint32_t n = step; if (pos + n > 131) n = 131 - pos;
        sha256_update(&c, sha_input + pos, n);
        pos += n; step = step % 17 + 1;
    }
    sha256_final(&c, d);
    sha256(sha_input, 131, e);
    check(memcmp(d, e, 32) == 0, "incremental updates == one-shot (131 bytes)");

    /* One million 'a' (FIPS 180 vector). */
    sha256_init(&c);
    uint8_t block[1000]; memset(block, 'a', sizeof block);
    for (int i = 0; i < 1000; i++) sha256_update(&c, block, 1000);
    sha256_final(&c, d);
    unhex("cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0", e, 32);
    check(memcmp(d, e, 32) == 0, "published vector: 1,000,000 x 'a'");
}

static void test_hmac(void)
{
    printf("== HMAC-SHA256 ==\n");
    int all = 1;
    for (unsigned i = 0; i < sizeof hmac_vecs / sizeof hmac_vecs[0]; i++)
    {
        uint8_t mac[32];
        hmac_sha256(hmac_vecs[i].key, hmac_vecs[i].kl, hmac_vecs[i].msg, hmac_vecs[i].ml, mac);
        if (memcmp(mac, hmac_vecs[i].mac, 32) != 0) { all = 0; printf("    mismatch vector %u\n", i); }
    }
    check(all, "40 vectors: key lengths 0..131 (incl. > block size)");

    /* RFC 4231 test case 2 */
    uint8_t mac[32], e[32];
    hmac_sha256((const uint8_t*)"Jefe", 4, (const uint8_t*)"what do ya want for nothing?", 28, mac);
    unhex("5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843", e, 32);
    check(memcmp(mac, e, 32) == 0, "RFC 4231 test case 2");
}

static void test_pbkdf2(void)
{
    printf("== PBKDF2-HMAC-SHA256 ==\n");
    for (unsigned i = 0; i < sizeof pbkdf2_vecs / sizeof pbkdf2_vecs[0]; i++)
    {
        uint8_t out[64];
        const pbkdf2_vec_t* v = &pbkdf2_vecs[i];
        pbkdf2_hmac_sha256(v->pw, v->pl, v->salt, v->sl, v->iter, out, v->dk);
        char name[64];
        snprintf(name, sizeof name, "vector %u (iter=%u, dkLen=%u)", i, v->iter, v->dk);
        check(memcmp(out, v->expect, v->dk) == 0, name);
    }
}

static void test_aes(void)
{
    printf("== AES-256 ==\n");

    /* FIPS-197 Appendix C.3 */
    uint8_t key[32], pt[16], ct[16], e[16];
    for (int i = 0; i < 32; i++) key[i] = (uint8_t)i;
    unhex("00112233445566778899aabbccddeeff", pt, 16);
    unhex("8ea2b7ca516745bfeafc49904b496089", e, 16);
    aes256_ctx_t ctx; aes256_init(&ctx, key); aes256_encrypt_block(&ctx, pt, ct);
    check(memcmp(ct, e, 16) == 0, "FIPS-197 C.3");

    /* NIST SP 800-38A F.1.5 (ECB-AES256), first block */
    unhex("603deb1015ca71be2b73aef0857d77811f352c073b6108d72d9810a30914dff4", key, 32);
    unhex("6bc1bee22e409f96e93d7e117393172a", pt, 16);
    unhex("f3eed1bdb5d2a03c064b5a7e3db181f8", e, 16);
    aes256_init(&ctx, key); aes256_encrypt_block(&ctx, pt, ct);
    check(memcmp(ct, e, 16) == 0, "SP 800-38A F.1.5 block 1");

    int all = 1;
    for (int i = 0; i < AES_VEC_COUNT; i++)
    {
        aes256_init(&ctx, aes_keys[i]);
        aes256_encrypt_block(&ctx, aes_pts[i], ct);
        if (memcmp(ct, aes_cts[i], 16) != 0) { all = 0; printf("    mismatch vector %d\n", i); }
    }
    check(all, "64 random key/plaintext pairs vs OpenSSL");

    /* in-place operation (in == out) is documented as supported */
    memcpy(ct, aes_pts[0], 16);
    aes256_init(&ctx, aes_keys[0]);
    aes256_encrypt_block(&ctx, ct, ct);
    check(memcmp(ct, aes_cts[0], 16) == 0, "in-place encrypt");

    /* The constant-time S-box must equal the FIPS-197 table for ALL inputs. */
    all = 1;
    for (int x = 0; x < 256; x++)
        if (aes256_sbox_for_test((uint8_t)x) != sbox_ref[x]) { all = 0; printf("    sbox mismatch at 0x%02x\n", x); }
    check(all, "computed S-box == FIPS-197 table (all 256 inputs)");
}

static void test_checksum(void)
{
    printf("== Internet checksum / byte order ==\n");

    /* Wikipedia IPv4 header example, checksum field zeroed */
    const uint8_t hdr[20] = {0x45,0x00,0x00,0x73,0x00,0x00,0x40,0x00,0x40,0x11,
                             0x00,0x00,0xc0,0xa8,0x00,0x01,0xc0,0xa8,0x00,0xc7};
    check(internet_checksum(hdr, 20) == 0xb861, "Wikipedia IPv4 header example");

    int all = 1;
    for (int l = 0; l <= 300; l++)
        if (internet_checksum(ck_input, (uint32_t)l) != ck_expect[l]) { all = 0; printf("    mismatch length %d\n", l); }
    check(all, "lengths 0..300 (odd/even) match RFC 1071 reference");

    uint32_t s = checksum_add(0, ck_input, 100);
    s = checksum_add(s, ck_input + 100, 100);
    check(checksum_finish(s) == ck_expect[200], "checksum_add across two even-length buffers");

    uint8_t b[4];
    net_write16(b, 0x1234); check(b[0] == 0x12 && b[1] == 0x34 && net_read16(b) == 0x1234, "net_read16/write16");
    net_write32(b, 0xdeadbeef); check(b[0] == 0xde && b[3] == 0xef && net_read32(b) == 0xdeadbeefu, "net_read32/write32");
}

int main(void)
{
    test_sha256();
    test_hmac();
    test_pbkdf2();
    test_aes();
    test_checksum();
    printf("\ncrypto/checksum tests: %d passed, %d failed\n", passed, failed);
    return failed ? 1 : 0;
}
